import{V as e,Z as t,et as n,mt as r,tt as i}from"./chunks/framework.Bb5YUzRP.js";import{A as a,D as o,E as s,O as c,T as l,k as u}from"./chunks/assets.DMxVpLII.js";var d=JSON.parse(`{"title":"Zones","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/zones.md","filePath":"product-config/zones.md"}`),f={name:`product-config/zones.md`},p=a+` 1x, `+u+` 2x`,m=c+` 1x, `+o+` 2x`,h=s+` 1x, `+l+` 2x`;function g(e,a,o,s,c,l){return r(),n(`div`,null,[...a[0]||=[i(`<h1 id="zones" tabindex="-1">Zones <a class="header-anchor" href="#zones" aria-label="Permalink to “Zones”">​</a></h1><p>Zones let you create <a href="/product-config/fields.html">fields</a> that follow any shape instead of a rectangle, for example a window with rounded corners or a slanted edge.</p><p>You draw the shapes in an SVG file, import it, then turn each shape into a field with one click. When the customer adds images, they are cropped to the shape of each zone, which is perfect for collages or non rectangular products.</p><p><img src="/webp/zones-collage.jpg-90-1794236257182.webp" srcset="`+p+`" alt="Zones collage" title="" width="1210" height="1186" loading="lazy" style="width:605px;"></p><h2 id="prepare-the-zones-file" tabindex="-1">Prepare the zones file <a class="header-anchor" href="#prepare-the-zones-file" aria-label="Permalink to “Prepare the zones file”">​</a></h2><p>Create an SVG file with the same proportions as the side image, and draw one path for each zone.</p><ul><li>Each <code>&lt;path&gt;</code> element becomes one zone</li><li>Shapes such as rectangles or circles must be converted to paths first (in Inkscape: <strong>Path &gt; Object to Path</strong>)</li><li>Use a <code>viewBox</code> that covers the whole image, so the zones line up with it</li></ul><p>Here&#39;s a <a href="/files/zones-sample.svg">sample file</a> you can start from.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The easiest way is to open the side image in your vector editor, draw the zones on top of it, then delete the image and save only the paths.</p></div><p>💿 This video shows how to prepare the path outlines in Illustrator</p>`,10),t(`iframe`,{width:`560`,height:`315`,src:`https://www.youtube.com/embed/psqLMEG-BSM`,title:`Prepare zones in Illustrator`,frameborder:`0`,allow:`accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture`,allowfullscreen:``},null,-1),i(`<h2 id="import-the-zones" tabindex="-1">Import the zones <a class="header-anchor" href="#import-the-zones" aria-label="Permalink to “Import the zones”">​</a></h2><p>In the <strong>Fields</strong> tab, click the zones button in the toolbar of the side and pick your SVG file.</p><p>The zones are displayed on top of the side image, each one with a <strong>+</strong> button.</p><p><img src="/webp/zones-admin.png-90-1794236257180.webp" srcset="`+m+`" alt="Zones" title="" width="1440" height="940" loading="lazy" style="width:720px;"></p><p>Click the <strong>+</strong> button of a zone to create a field with that shape. The field is created as an image field. You can then edit it like any other field (label, type, cost...).</p><p>Zones are saved per side, per image and per model, so each combination image or model can have its own zones file.</p><h2 id="remove-the-zones" tabindex="-1">Remove the zones <a class="header-anchor" href="#remove-the-zones" aria-label="Permalink to “Remove the zones”">​</a></h2><p>Click the zones button again to remove the imported file. The fields you already created from the zones are kept.</p><h2 id="customer-display" tabindex="-1">Customer display <a class="header-anchor" href="#customer-display" aria-label="Permalink to “Customer display”">​</a></h2><p>On the product page, the content of the field is clipped to its shape. The outline of the zone is displayed when the customer hovers the design area.</p><p>While the customer edits an item inside the field, the whole item is visible so it can be moved and resized easily. Once the field is no longer active, the item is clipped again.</p><p><img src="/webp/zones-front.png-90-1794236257184.webp" srcset="`+h+`" alt="Zones display" title="" width="1190" height="700" loading="lazy" style="width:595px;"></p><p>The shape is also applied to the files generated for production.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The shape only hides the parts that are outside of the zone. It does not prevent the customer from moving an item outside of it, and the item cost is still calculated from the full size of the item.</p></div>`,14)]])}var _=e(f,[[`render`,g]]);export{d as __pageData,_ as default};